const g = k => (dv[k] == null ? "" : String(dv[k])).trim();
const problems = [];
const suggestions = {};
if (!g("first_name") && !g("company_name")) problems.push({field: "first_name", issue: "missing - need at least one name for the booking"});
if (!g("company_name")) problems.push({field: "company_name", issue: "missing"});
let cb = g("callback_number");
if (!/^\+[1-9]\d{6,14}$/.test(cb)) {
  const digits = cb.replace(/\D/g, "");
  if (digits.length === 10) suggestions["callback_number"] = "+1" + digits;
  else problems.push({field: "callback_number", issue: cb ? "not E.164" : "missing"});
}
if (["America/New_York","America/Chicago","America/Denver","America/Los_Angeles"].indexOf(g("prospect_timezone")) < 0)
  problems.push({field: "prospect_timezone", issue: "not IANA"});
const st = g("selected_time") || g("requested_slot");
if (!st) problems.push({field: "selected_time", issue: "no confirmed slot"});
return { data_complete: problems.length === 0, problems, suggestions };
